import React from "react";
import { Box, Paper, Typography, Chip, CircularProgress } from "@mui/material";
import { History as HistoryIcon } from "@mui/icons-material";

function formatTimestamp(value) {
  if (!value) return "N/A";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleString("en-US", {
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    hour12: true,
  });
}

function formatChangeType(changeType) {
  if (!changeType) return "Update";
  return changeType
    .split("_")
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
}

function getAssigneeName(entry, field) {
  if (field === "from") {
    return (
      entry?.from_assignee?.name ||
      entry?.assignment_from?.name ||
      entry?.assignment_from ||
      null
    );
  }
  return (
    entry?.to_assignee?.name ||
    entry?.assignment_to?.name ||
    entry?.assignment_to ||
    null
  );
}

function HistoryEntry({ entry }) {
  const isCreation =
    entry?.change_type === "ticket_created" ||
    entry?.change_type === "created" ||
    (!entry?.status_from && entry?.status_to);

  const statusChanged =
    entry?.status_from &&
    entry?.status_to &&
    entry.status_from !== entry.status_to;

  const priorityChanged =
    entry?.priority_from &&
    entry?.priority_to &&
    entry.priority_from !== entry.priority_to;

  const assigneeFrom = getAssigneeName(entry, "from");
  const assigneeTo = getAssigneeName(entry, "to");
  const assignmentChanged =
    (assigneeFrom || assigneeTo) && assigneeFrom !== assigneeTo;

  return (
    <Box
      sx={{
        display: "flex",
        gap: 2,
        position: "relative",
        pb: 3,
        "&:last-child": { pb: 0 },
        "&::before": {
          content: '""',
          position: "absolute",
          left: 11,
          top: 28,
          bottom: 0,
          width: 2,
          bgcolor: "#e5e7eb",
        },
        "&:last-child::before": { display: "none" },
      }}
    >
      <Box
        sx={{
          width: 24,
          height: 24,
          borderRadius: "50%",
          bgcolor: isCreation ? "#1976d2" : "#43B02A",
          border: "3px solid #fff",
          boxShadow: "0 0 0 2px #e5e7eb",
          flexShrink: 0,
          zIndex: 1,
          mt: 0.5,
        }}
      />
      <Paper
        elevation={0}
        sx={{
          flex: 1,
          p: 2,
          borderRadius: 2,
          bgcolor: "#ffffff",
          border: "1px solid #e5e7eb",
        }}
      >
        <Box
          sx={{
            display: "flex",
            flexWrap: "wrap",
            alignItems: "center",
            gap: 1,
            mb: 1,
          }}
        >
          <Chip
            size="small"
            label={formatChangeType(entry?.change_type)}
            sx={{
              bgcolor: isCreation ? "#e3f2fd" : "#e8f5e9",
              color: isCreation ? "#1565c0" : "#2e7d32",
              fontWeight: 600,
              fontSize: "0.75rem",
            }}
          />
          <Typography variant="caption" sx={{ color: "#6b7280", ml: "auto" }}>
            {formatTimestamp(entry?.created_at)}
          </Typography>
        </Box>

        {entry?.message && (
          <Typography
            variant="body2"
            sx={{ color: "#1f2937", mb: 1, lineHeight: 1.6 }}
          >
            {entry.message}
          </Typography>
        )}

        {statusChanged && (
          <Typography variant="body2" sx={{ color: "#374151", mb: 0.5 }}>
            <strong>Status:</strong> {entry.status_from} → {entry.status_to}
          </Typography>
        )}

        {!statusChanged && entry?.status_to && (
          <Typography variant="body2" sx={{ color: "#374151", mb: 0.5 }}>
            <strong>Status:</strong> {entry.status_to}
          </Typography>
        )}

        {priorityChanged && (
          <Typography variant="body2" sx={{ color: "#374151", mb: 0.5 }}>
            <strong>Priority:</strong> {entry.priority_from} →{" "}
            {entry.priority_to}
          </Typography>
        )}

        {assignmentChanged && (
          <Typography variant="body2" sx={{ color: "#374151", mb: 0.5 }}>
            <strong>Assignee:</strong> {assigneeFrom || "Unassigned"} →{" "}
            {assigneeTo || "Unassigned"}
          </Typography>
        )}

        {entry?.user?.name && (
          <Typography variant="caption" sx={{ color: "#6b7280" }}>
            By {entry.user.name}
          </Typography>
        )}
      </Paper>
    </Box>
  );
}

const TicketHistoryTimeline = ({ history = [], loading = false }) => {
  if (loading) {
    return (
      <Box sx={{ display: "flex", justifyContent: "center", py: 4 }}>
        <CircularProgress size={32} sx={{ color: "#4CAF50" }} />
      </Box>
    );
  }

  if (!history.length) {
    return (
      <Box
        sx={{
          textAlign: "center",
          py: 4,
          color: "#6b7280",
        }}
      >
        <HistoryIcon sx={{ fontSize: 40, mb: 1, opacity: 0.5 }} />
        <Typography variant="body2">
          No history recorded for this ticket
        </Typography>
      </Box>
    );
  }

  return (
    <Box sx={{ pl: 0.5 }}>
      {history.map((entry) => (
        <HistoryEntry
          key={entry.id || `${entry.created_at}-${entry.change_type}`}
          entry={entry}
        />
      ))}
    </Box>
  );
};

export default TicketHistoryTimeline;
