export const WAITING_FOR_PARTS_STATUS = "Waiting for Parts";

export const BASE_TICKET_STATUSES = [
  "New",
  "Assigned",
  "In Progress",
  "Pending Confirmation",
  "Resolved",
  "Closed",
];

export const FILTER_TICKET_STATUSES = [
  ...BASE_TICKET_STATUSES.slice(0, 3),
  WAITING_FOR_PARTS_STATUS,
  ...BASE_TICKET_STATUSES.slice(3),
];

export function isItOrMaintenanceDepartment(departmentName) {
  if (!departmentName) return false;
  const normalized = String(departmentName).trim().toLowerCase();
  return (
    normalized === "information technology" || normalized === "maintenance"
  );
}

/** Status options for ticket detail view (IT/Maintenance include Waiting for Parts). */
export function getTicketStatusOptions(departmentName) {
  if (!isItOrMaintenanceDepartment(departmentName)) {
    return [...BASE_TICKET_STATUSES];
  }

  const options = [...BASE_TICKET_STATUSES];
  const inProgressIndex = options.indexOf("In Progress");
  if (inProgressIndex !== -1) {
    options.splice(inProgressIndex + 1, 0, WAITING_FOR_PARTS_STATUS);
  } else {
    options.push(WAITING_FOR_PARTS_STATUS);
  }
  return options;
}

export function canUseWaitingForPartsStatus(departmentName) {
  return isItOrMaintenanceDepartment(departmentName);
}

/** Status options for executive / assigned ticket detail view. */
export function getExecutiveStatusOptions(departmentName) {
  const options = ["In Progress", "Pending Confirmation", "Resolved", "Closed"];
  if (!isItOrMaintenanceDepartment(departmentName)) {
    return options;
  }
  const inProgressIndex = options.indexOf("In Progress");
  if (inProgressIndex !== -1) {
    options.splice(inProgressIndex + 1, 0, WAITING_FOR_PARTS_STATUS);
  }
  return options;
}

export function getStatusColorValue(status) {
  switch (status) {
    case "New":
      return "#1976d2";
    case "Assigned":
      return "#7b1fa2";
    case "In Progress":
      return "#ff9800";
    case WAITING_FOR_PARTS_STATUS:
      return "#ed6c02";
    case "Pending Confirmation":
      return "#26a69a";
    case "Resolved":
      return "#4caf50";
    case "Closed":
      return "#666666";
    default:
      return "#666666";
  }
}
